def isValid(word: str) -> bool:
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}

    # Condition 1: must contain at least 3 characters
    if len(word) < 3:
        return False

    has_vowel = False
    has_consonant = False

    for ch in word:
        # Condition 2: only digits and English letters are allowed
        if not (ch.isdigit() or ('a' <= ch <= 'z') or ('A' <= ch <= 'Z')):
            return False
        # Conditions 3 & 4: track vowels and consonants
        if ch in vowels:
            has_vowel = True
        else:
            has_consonant = True

    return has_vowel and has_consonant
