import sys

def main():
    data = sys.stdin.read().split()
    idx = 0

    def read_block():
        nonlocal idx
        h = int(data[idx]); w = int(data[idx + 1]); idx += 2
        grid = data[idx:idx + h]; idx += h
        return h, w, grid

    hA, wA, Ag = read_block()
    hB, wB, Bg = read_block()
    hX, wX, Xg = read_block()

    def to_masks(grid):
        masks = []
        for row in grid:
            m = 0
            for j, ch in enumerate(row):
                if ch == '#':
                    m |= 1 << j
            masks.append(m)
        return masks

    Am = to_masks(Ag)
    Bm = to_masks(Bg)
    Xm = to_masks(Xg)

    def extents(masks):
        rs = [i for i, m in enumerate(masks) if m]
        cs = set()
        for m in masks:
            mm = m; j = 0
            while mm:
                if mm & 1:
                    cs.add(j)
                mm >>= 1; j += 1
        return min(rs), max(rs), min(cs), max(cs)

    armin, armax, acmin, acmax = extents(Am)
    brmin, brmax, bcmin, bcmax = extents(Bm)

    def gen_placements(masks, rmin, rmax, cmin, cmax):
