from math import gcd

def countBeautifulPairs(nums):
    def first_digit(x):
        while x >= 10:
            x //= 10
        return x

    count = 0
    n = len(nums)
    for i in range(n):
        f = first_digit(nums[i])
        for j in range(i + 1, n):
            l = nums[j] % 10
            if gcd(f, l) == 1:
                count += 1
    return count
