def minimumSum(nums):
    n = len(nums)
    best = float('inf')

    for j in range(1, n - 1):
        # Find minimum value on the left that is strictly less than nums[j]
        left_min = None
        for i in range(j):
            if nums[i] < nums[j]:
                if left_min is None or nums[i] < left_min:
                    left_min = nums[i]

        # Find minimum value on the right that is strictly less than nums[j]
        right_min = None
        for k in range(j + 1, n):
            if nums[k] < nums[j]:
                if right_min is None or nums[k] < right_min:
                    right_min = nums[k]

        # If both a valid left and right peak neighbor exist, form a mountain
        if left_min is not None and right_min is not None:
            best = min(best, left_min + nums[j] + right_min)

    return best if best != float('inf') else -1
